// stockUniqueKeys are the conflict targets of Stock's unique keys, and
// the assignment an upsert that sets nothing writes, so the row it
// conflicts with is returned (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert only if changed reads back, empty for a
// key over an expression, and the key's columns as a batch insert's cells
// name them (D89).
var stockUniqueKeys = map[StockUniqueKey]struct {
	conflict, keep, rows string
	columns              []string
}{
	StockUniqueById: {`(id)`, `id = EXCLUDED.id`, `SELECT "id", "shelf_id", "ingredient", "quantity", "_version" FROM stock WHERE (id) IN (%s)`, []string{`id`}},
}

// stockKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func stockKeyOf(on StockUniqueKey, row *types.Stock) (string, bool) {
	switch on {
	case StockUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *StockRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Stock, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *StockRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Stock, error) {
	result := &types.Stock{}
	// Create temporary variables for nullable fields that need pointer scanning

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelShelf *types.IdentityUUID

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&tempRelShelf,

		&result.Ingredient,

		&result.Quantity,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	// Set relationship IDs from scanned FK values
	if tempRelShelf != nil {
		result.Shelf.Id = stockUUIDPtr(*tempRelShelf)
	}

	return result, nil
}

// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes what CreateOne writes and the update what
// UpdateOne writes, updated_at and updated_by among it, but an update that
// sets no field leaves the row as it is.
func (r *StockRepository) UpsertOne(ctx context.Context, input *types.Stock, on StockUniqueKey, update *StockUpdate) (*types.Stock, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with the row: inserted it,
// updated the row that held the key, or left that row as it was (D89).
// With opts.OnlyIfChanged it updates the row only when a field the update
// sets differs from what the row holds, which it reads back otherwise. A write that
// may take more than one statement runs in a transaction of its own when
// none is open.
func (r *StockRepository) UpsertOneResult(ctx context.Context, input *types.Stock, on StockUniqueKey, update *StockUpdate, opts *UpsertOptions) (UpsertResult[*types.Stock], error) {
	var none UpsertResult[*types.Stock]
	key, ok := stockUniqueKeys[on]
	if !ok {
		return none, fmt.Errorf("orm: Stock has no unique key %q", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if opts.OnlyIfChanged && key.rows == "" {
		return none, upsertExpressionKey("UpsertOneResult", "Stock", string(on))
	}
	if update == nil {
		update = &StockUpdate{}
	}
	write := func(repo *StockRepository) (UpsertResult[*types.Stock], error) {
		result, err := repo.upsertRow(ctx, input, on, update, opts.OnlyIfChanged)
		if err != nil {
			return none, err
		}
		return *result, nil
	}
	if !opts.OnlyIfChanged {
		return write(r)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (UpsertResult[*types.Stock], error) {
		return write(&StockRepository{tx: tx, txDB: r.database()})
	})
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, only if changed, and the second
// statement of an encrypted field.
func (r *StockRepository) upsertRow(ctx context.Context, input *types.Stock, on StockUniqueKey, update *StockUpdate, onlyIfChanged bool) (*UpsertResult[*types.Stock], error) {
	key := stockUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := stockUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: ingredient
	fields = append(fields, `ingredient`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Ingredient)
	// Required field: quantity
	fields = append(fields, `quantity`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Quantity)

	// Handle relationship foreign key columns
	// Relationship: shelf (FK: shelf_id)
	{
		var zeroId types.IdentityUUID
		if relID, ok := stockUUIDValue(input.Shelf.Id); ok && relID != zeroId {
			fields = append(fields, `shelf_id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, relID.ToUUID())
		}
	}

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Ingredient != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`ingredient = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `stock.ingredient`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Ingredient)
	}
	if update.Quantity != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`quantity = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `stock.quantity`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Quantity)
	}
	// Handle relationship foreign key: shelf
	if update.ShelfID != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("shelf_id = $%d", paramNum))
		compareCurrent = append(compareCurrent, `stock.shelf_id`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, update.ShelfID.ToUUID())
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field leaves the row as it is, stamps and
		// all, and returns it.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO stock (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "shelf_id", "ingredient", "quantity", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Stock]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Stock]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with already held the update's values.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Stock row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Stock{input})
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Stock]{Row: found[0], Status: UpsertUnchanged}
	}
	return upserted, nil
}

// UpsertMany inserts each input, or, when a row already holds its value of
// the unique key on, sets each field update names of that row to the value
// the input would have inserted, and returns each input's row and what it
// did with it, in the inputs' order (D89). One statement writes a batch of
// rows, opts.Batch or as many as Postgres binds the parameters of, and more
// rows take a statement per batch, in one transaction; a write that may
// take more than one statement runs in a transaction of its own when none
// is open. An update that names no field leaves each row that holds a key
// as it is. Two inputs of one batch that hold one key fail
// the statement, and a key over an expression, whose rows the statement's
// cannot be matched to the inputs by, is refused.
func (r *StockRepository) UpsertMany(ctx context.Context, inputs []*types.Stock, on StockUniqueKey, update StockFields, opts *UpsertOptions) ([]UpsertResult[*types.Stock], error) {
	key, ok := stockUniqueKeys[on]
	if !ok {
		return nil, fmt.Errorf("orm: Stock has no unique key %q", string(on))
	}
	if key.rows == "" {
		return nil, upsertExpressionKey("UpsertMany", "Stock", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if update.Id {
		return nil, fmt.Errorf("orm: UpsertMany of Stock sets the fields an update sets, not id")
	}
	if update.Version {
		return nil, fmt.Errorf("orm: UpsertMany of Stock sets the fields an update sets, not _version")
	}
	batch, err := upsertBatch("Stock", opts.Batch, 16383)
	if err != nil {
		return nil, err
	}
	if len(inputs) == 0 {
		return []UpsertResult[*types.Stock]{}, nil
	}
	if len(inputs) <= batch && !opts.OnlyIfChanged {
		return r.upsertBatches(ctx, inputs, on, update, batch, false)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]UpsertResult[*types.Stock], error) {
		return (&StockRepository{tx: tx, txDB: r.database()}).upsertBatches(ctx, inputs, on, update, batch, opts.OnlyIfChanged)
	})
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// only if changed, and the second statement of each encrypted field.
func (r *StockRepository) upsertBatches(ctx context.Context, inputs []*types.Stock, on StockUniqueKey, update StockFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Stock], error) {
	key := stockUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Ingredient {
		setClauses = append(setClauses, `ingredient = EXCLUDED.ingredient`)
		compareCurrent = append(compareCurrent, `stock.ingredient`)
		compareNext = append(compareNext, `EXCLUDED.ingredient`)
	}
	if update.Quantity {
		setClauses = append(setClauses, `quantity = EXCLUDED.quantity`)
		compareCurrent = append(compareCurrent, `stock.quantity`)
		compareNext = append(compareNext, `EXCLUDED.quantity`)
	}
	if update.Shelf {
		setClauses = append(setClauses, `shelf_id = EXCLUDED.shelf_id`)
		compareCurrent = append(compareCurrent, `stock.shelf_id`)
		compareNext = append(compareNext, `EXCLUDED.shelf_id`)
	}

	results := make([]UpsertResult[*types.Stock], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := stockUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: ingredient
			{
				cell := batchInsertCell{column: `ingredient`, set: true}
				cell.value = input.Ingredient
				row = append(row, cell)
			}
			// Required field: quantity
			{
				cell := batchInsertCell{column: `quantity`, set: true}
				cell.value = input.Quantity
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			// Relationship: shelf (FK: shelf_id)
			{
				cell := batchInsertCell{column: `shelf_id`}
				var zeroId types.IdentityUUID
				if relID, ok := stockUUIDValue(input.Shelf.Id); ok && relID != zeroId {
					cell.value, cell.set = relID.ToUUID(), true
				}
				row = append(row, cell)
			}
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field leaves each row as it is.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO stock (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "shelf_id", "ingredient", "quantity", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = stockKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Stock], len(prepared))
		for n, row := range returned {
			text, ok := stockKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Stock wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Stock]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, only if changed,
		// which it reads back by its key, or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged {
				return nil, fmt.Errorf("the Stock row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Stock, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Stock row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Stock]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *StockRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Stock, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Stock
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert only if changed left as they were
// (D89). A key no live row holds is ErrNotFound.
func (r *StockRepository) rowsOfKeys(ctx context.Context, on StockUniqueKey, keys [][]any, inputs []*types.Stock) ([]*types.Stock, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(stockUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Stock{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := stockKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Stock, len(inputs))
	for i, input := range inputs {
		text, _ := stockKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Stock row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// CreateMany inserts multiple Stock records in a single statement
func (r *StockRepository) CreateMany(ctx context.Context, inputs []*types.Stock) ([]*types.Stock, error) {
	if len(inputs) == 0 {
		return []*types.Stock{}, nil
	}

	// Set audit fields

	// Build the batch INSERT in one pass over the fields. Each row records every
	// candidate column in the same order, with the value it binds or no value
	// when it leaves an optional column unset; buildBatchInsert inserts the
	// columns any row sets and writes DEFAULT for a row that leaves one unset.
	batch := make([][]batchInsertCell, 0, len(inputs))
	for _, input := range inputs {
		var row []batchInsertCell
		// Primary key: id. Schema-owned identities may supply a stable
		// UUID, matching CreateOne; a row without one takes the generated default.
		{
			cell := batchInsertCell{column: `id`}
			var zeroPrimaryKey types.IdentityUUID
			if primaryKey, ok := stockUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
				cell.value, cell.set = primaryKey.ToUUID(), true
			}
			row = append(row, cell)
		}
		// Required field: ingredient
		{
			cell := batchInsertCell{column: `ingredient`, set: true}
			cell.value = input.Ingredient
			row = append(row, cell)
		}
		// Required field: quantity
		{
			cell := batchInsertCell{column: `quantity`, set: true}
			cell.value = input.Quantity
			row = append(row, cell)
		}

		// Relationship foreign key columns, matching CreateOne
		// Relationship: shelf (FK: shelf_id)
		{
			cell := batchInsertCell{column: `shelf_id`}
			var zeroId types.IdentityUUID
			if relID, ok := stockUUIDValue(input.Shelf.Id); ok && relID != zeroId {
				cell.value, cell.set = relID.ToUUID(), true
			}
			row = append(row, cell)
		}
		batch = append(batch, row)
	}
	fieldNames, valuePlaceholders, values := buildBatchInsert(batch)

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	returningClauseMany := `"id", "shelf_id", "ingredient", "quantity", "_version"`
	query := fmt.Sprintf(
		`INSERT INTO stock (%s) VALUES %s RETURNING %s`,
		strings.Join(fieldNames, ", "),
		strings.Join(valuePlaceholders, ", "),
		returningClauseMany,
	)

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute batch insert: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Stock{}
	for rows.Next() {
		result := &types.Stock{}
		// Create temporary variables for nullable fields that need pointer scanning

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)
		var tempRelShelf *types.IdentityUUID

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&result.Id,

			&tempRelShelf,

			&result.Ingredient,

			&result.Quantity,

			&result.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}

		// Copy nullable fields when present

		// Set relationship IDs from scanned FK values
		if tempRelShelf != nil {
			result.Shelf.Id = stockUUIDPtr(*tempRelShelf)
		}
		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}

	return results, nil
}

// UpdateOne updates a single Stock record by ID
func (r *StockRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *StockUpdate) (*types.Stock, error) {
	return r.updateOne(ctx, id, update, nil)
}

// UpdateOneIfVersion updates a single Stock only if its current _version matches expectedVersion.
// It returns ErrVersionConflict when the row exists at another version and
// ErrNotFound when it does not exist.
func (r *StockRepository) UpdateOneIfVersion(ctx context.Context, id types.IdentityUUID, expectedVersion int64, update *StockUpdate) (*types.Stock, error) {
	return r.updateOne(ctx, id, update, &expectedVersion)
}

// versionMiss tells apart why a write fenced on _version matched no row:
// ErrVersionConflict when the row exists at another version, ErrNotFound when
// it does not exist.
func (r *StockRepository) versionMiss(ctx context.Context, id types.IdentityUUID) error {
	query := `SELECT _version FROM stock WHERE id = $1`

	var version int64
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, id.ToUUID())
	} else {
		row = r.db.pool.QueryRow(ctx, query, id.ToUUID())
	}
	if err := row.Scan(&version); err != nil {
		if err == pgx.ErrNoRows {
			return ErrNotFound
		}
		return fmt.Errorf("failed to read Stock version: %w", err)
	}
	return ErrVersionConflict
}

func (r *StockRepository) updateOne(ctx context.Context, id types.IdentityUUID, update *StockUpdate, expectedVersion *int64) (*types.Stock, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Ingredient != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`ingredient = $%d`, paramNum))
		values = append(values, *update.Ingredient)
	}
	if update.Quantity != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`quantity = $%d`, paramNum))
		values = append(values, *update.Quantity)
	}
	// Handle relationship foreign key: shelf
	if update.ShelfID != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("shelf_id = $%d", paramNum))
		values = append(values, update.ShelfID.ToUUID())
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return nil, fmt.Errorf("no fields to update")
	}

	paramNum++
	values = append(values, id.ToUUID())

	query := fmt.Sprintf(
		`UPDATE stock SET %s WHERE id = $%d`,
		strings.Join(setClauses, ", "),
		paramNum,
	)
	if expectedVersion != nil {
		paramNum++
		values = append(values, *expectedVersion)
		query += fmt.Sprintf(" AND _version = $%d", paramNum)
	}

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	query += ` RETURNING "id", "shelf_id", "ingredient", "quantity", "_version"`

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}

	// Scan result
	result := &types.Stock{}
	// Create temporary variables for nullable fields that need pointer scanning

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelShelf *types.IdentityUUID

	// Scan all fields in schema order (matches DDL column order)
	if err := row.Scan(

		&result.Id,

		&tempRelShelf,

		&result.Ingredient,

		&result.Quantity,

		&result.Version,
	); err != nil {
		if err == pgx.ErrNoRows {
			if expectedVersion != nil {
				return nil, r.versionMiss(ctx, id)
			}
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan result: %w", err)
	}

	// Copy nullable fields when present

	// Set relationship IDs from scanned FK values
	if tempRelShelf != nil {
		result.Shelf.Id = stockUUIDPtr(*tempRelShelf)
	}

	return result, nil
}

// UpdateMany updates multiple Stock records matching the filter
func (r *StockRepository) UpdateMany(ctx context.Context, filter *StockFilter, update *StockUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Ingredient != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`ingredient = $%d`, paramNum))
		values = append(values, *update.Ingredient)
	}
	if update.Quantity != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`quantity = $%d`, paramNum))
		values = append(values, *update.Quantity)
	}
	// Handle relationship foreign key: shelf
	if update.ShelfID != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("shelf_id = $%d", paramNum))
		values = append(values, update.ShelfID.ToUUID())
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE stock SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Stock record by ID
func (r *StockRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	query := `DELETE FROM stock WHERE id = $1`

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, id.ToUUID())
	} else {
		result, err = r.db.pool.Exec(ctx, query, id.ToUUID())
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

// DeleteOneIfVersion permanently deletes a single Stock only if its
// current _version matches expectedVersion. It returns ErrVersionConflict when
// the row exists at another version and ErrNotFound when it does not exist.
func (r *StockRepository) DeleteOneIfVersion(ctx context.Context, id types.IdentityUUID, expectedVersion int64) error {
	query := `DELETE FROM stock WHERE id = $1 AND _version = $2`
	queryArgs := []interface{}{id.ToUUID(), expectedVersion}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return r.versionMiss(ctx, id)
	}

	return nil
}

// DeleteMany permanently deletes multiple Stock records matching the filter
func (r *StockRepository) DeleteMany(ctx context.Context, filter *StockFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM stock%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
